; keep.asm -- chapter 21: the bits each register keeps
; generated by gen21.py
        INCLUDE "msx.inc"
        OUTPUT "keep.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; $FF written to each of the eight registers, the interrupts off; the debugger
; reads them back at 'kept'. Then 0 to each, read at 'zero'.
init:   di
        ld sp, SYS_AREA
        VDP_REG 0, $FF
        VDP_REG 1, $FF
        VDP_REG 2, $FF
        VDP_REG 3, $FF
        VDP_REG 4, $FF
        VDP_REG 5, $FF
        VDP_REG 6, $FF
        VDP_REG 7, $FF
kept:   nop
        VDP_REG 0, $00
        VDP_REG 1, $00
        VDP_REG 2, $00
        VDP_REG 3, $00
        VDP_REG 4, $00
        VDP_REG 5, $00
        VDP_REG 6, $00
        VDP_REG 7, $00
zero:   nop
done:   jr done
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
